# Preserve authored HTML and TeX, but encode comparison signs in ordinary prose.
def safe_comparisons(value):
 if isinstance(value,str):
  chunks=re.split('(\\\\\\([\\s\\S]*?\\\\\\)|\\\\\\[[\\s\\S]*?\\\\\\])',value)
  for i in range(0,len(chunks),2):
   chunks[i]=re.sub(r'<(?!/?(?:p|h[1-6]|strong|em|ol|ul|li|a|table|thead|tbody|tr|th|td|br|code|sup|sub|span)\b(?:\s[^<>]*?)?/?>)', '&lt;', chunks[i])
  return ''.join(chunks)
 if isinstance(value,list):return [safe_comparisons(x) for x in value]
 if isinstance(value,tuple):return tuple(safe_comparisons(x) for x in value)
 if isinstance(value,dict):return {k:safe_comparisons(v) for k,v in value.items()}
 return value
